import{S as s}from"./config-B7scZ5KD.js";/* empty css              */document.querySelectorAll('[href="[APP_STORE_URL]"]').forEach(e=>e.href=s.appStoreUrl);const t=document.getElementById("main-header");window.addEventListener("scroll",()=>{window.scrollY>50?t.classList.add("scrolled"):t.classList.remove("scrolled")});const o=new IntersectionObserver(e=>{e.forEach(r=>{r.isIntersecting&&(r.target.style.opacity="1",r.target.style.transform="translateY(0)")})},{threshold:.1});document.querySelectorAll(".feature-card, .section-header, .mascot-image").forEach(e=>{e.style.opacity="0",e.style.transform="translateY(30px)",e.style.transition="all 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275)",o.observe(e)});
